func tsAuthGRUConfig(t *testing.T) (WorkloadProfile, workload.ServiceSpec) {
	t.Helper()
	profile, err := readReleaseProfile("../../deploy/oci-region/ts-auth-gru-1-profile.json")
	if err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile("../../deploy/oci-region/ts-auth-gru-1-service.json")
	if err != nil {
		t.Fatal(err)
	}
	var spec workload.ServiceSpec
	if err := json.Unmarshal(data, &spec, json.RejectUnknownMembers(true)); err != nil {
		t.Fatal(err)
	}
	return profile, spec
}

func readReleaseProfile(path string) (WorkloadProfile, error) {
	data, err := readBoundedConfigFile(path)
	if err != nil {
		return WorkloadProfile{}, err
	}
	var profile WorkloadProfile
	if err := json.Unmarshal(data, &profile, json.RejectUnknownMembers(true)); err != nil {
		return WorkloadProfile{}, fmt.Errorf("parse workload profile: %w", err)
	}
	return profile, nil
}

func validateWorkloadProfiles(cell string, profiles map[string]WorkloadProfile) error {
	for role, profile := range profiles {
		if !grantToken.MatchString(role) || profile.Resources.CPU <= 0 || profile.Resources.CPU > 4096 ||
			profile.Resources.MemoryBytes <= 0 || profile.Resources.MemoryBytes > 1<<50 ||
			profile.Resources.DiskBytes <= 0 || profile.Resources.DiskBytes > 1<<50 {
			return fmt.Errorf("invalid workload resource profile for role %q", role)
		}
		if len(profile.Args) > 64 || len(profile.Env) > 64 {
			return fmt.Errorf("workload profile for %q exceeds argument or environment limit", role)
		}
		for _, arg := range profile.Args {
			if len(arg) > 4096 {
				return fmt.Errorf("workload argument for %q is too long", role)
			}
		}
		for key, value := range profile.Env {
			if key == "" || len(value) > 4096 {
				return fmt.Errorf("workload environment for %q is invalid", role)
			}
		}
		for key := range profile.Secrets {
			if role == terrabase.Role && !vaultsecret.FileKey(key) {
				return fmt.Errorf("workload profile for %q takes only Vault secret files (keys ending in _FILE)", role)
			}
			if roleidentity.Reserved(role, key) {
				return fmt.Errorf("workload profile for %q: the host sets %s for its NATS identity", role, key)
			}
		}
		for key := range profile.Env {
			if roleidentity.Reserved(role, key) {
				return fmt.Errorf("workload profile for %q: the host sets %s for its NATS identity", role, key)
			}
		}
		if err := vaultsecret.ValidateRefs(cell, role, profile.Secrets, profile.Env); err != nil {
			return fmt.Errorf("workload profile for %q: %w", role, err)
		}
		// Secret names start with the role, so a longer role would share them.
		for other := range profiles {
			if len(profile.Secrets) != 0 && strings.HasPrefix(other, role+"-") {
				return fmt.Errorf("workload profile for %q names Vault secrets, so no role may extend its name (%q)", role, other)
			}
		}
		// A terrabase profile with settings configures the C# TerraBase
		// binary. Arguments would override the host-owned settings.
		if role == terrabase.Role && len(profile.Env) != 0 {
			if _, err := terrabase.ParseProfile(profile.Env); err != nil {
				return fmt.Errorf("workload profile for %q: %w", role, err)
			}
			if len(profile.Args) != 0 {
				return fmt.Errorf("workload profile for %q sets TerraBase settings only through env", role)
			}
		}
		// The ts-auth profile is signed and readable: it must hold every
		// setting and name its secrets, which hosts read from the Vault.
		if role == tsauth.Role {
			if err := tsauth.ValidateProfile(cell, profile.Args, profile.Env, profile.Secrets); err != nil {
				return fmt.Errorf("workload profile for %q: %w", role, err)
			}
			if err := tsauth.ValidateMembers(profile.Env, profiles[terrabase.Role].Env); err != nil {
				return fmt.Errorf("workload profile for %q: %w", role, err)
			}
		}
	}
	return nil
}

func validateAutoscaleConfig(config *AutoscaleConfig, profiles map[string]WorkloadProfile) error {
	if config == nil {
		return nil
	}
	if err := workload.ValidateSpecs(config.Services); err != nil {
		return fmt.Errorf("autoscale services: %w", err)
	}
	for _, spec := range config.Services {
		if spec.Kind != workload.KindStateless {
			// Nothing reconciles stateful services yet (TerraBase is sized
			// by placement); refuse signed config that would silently do
			// nothing.
			return fmt.Errorf("autoscale service %q: stateful services are not reconciled yet", spec.Role)
		}
		if spec.Scaling != nil {
			for _, signal := range spec.Scaling.Signals {
				if !hostload.StatelessSignal(signal.Name) {
					// Request rates and TerraBase signals have no producer
					// for the stateless services this reconciler owns.
					return fmt.Errorf("autoscale service %q: signal %q has no producer for stateless services", spec.Role, signal.Name)
				}
			}
		}
		if spec.Role == "terrabase" {
			// TerraBase members are owned by placement, never by the
			// stateless reconciler or release shaping.
			return fmt.Errorf("autoscale service %q is a managed TerraBase role", spec.Role)
		}
		// ts-auth runs exactly its replica count, or none while a cell spec
		// drains it before removing it.
		if spec.Role == tsauth.Role && (spec.Replicas != workload.ReplicaBounds{Min: tsauth.Replicas, Max: tsauth.Replicas} &&
			spec.Replicas != workload.ReplicaBounds{} || spec.Placement.MaxPerFailureDomain != 1) {
			return fmt.Errorf("autoscale service %q must keep exactly %d replicas (or 0 to drain it) with one per failure domain",
				spec.Role, tsauth.Replicas)
		}
		profile, exists := profiles[spec.Role]
		if !exists {
			return fmt.Errorf("autoscale service %q has no workload profile", spec.Role)
		}
		if spec.Resources != (placement.Resources{}) && spec.Resources != profile.Resources {
			return fmt.Errorf("autoscale service %q resources differ from its workload profile", spec.Role)
		}
	}
	return nil
}

func ValidateProfile(cell string, args []string, env map[string]string, secrets map[string]vaultsecret.Ref) error {
	if _, ok := catalog.LookupName(cell); !ok {
		return fmt.Errorf("ts-auth needs a catalog cell, not %q", cell)
	}
	if len(args) != 0 {
		return errors.New("ts-auth profile sets its settings only through env")
	}
	if slices.ContainsFunc(Secrets, func(key string) bool { _, ok := secrets[key]; return !ok }) {
		return fmt.Errorf("ts-auth profile secrets must name %s", strings.Join(Secrets, ", "))
	}
	for key := range secrets {
		if !slices.Contains(Secrets, key) && !slices.Contains(OptionalSecrets, key) {
			return fmt.Errorf("ts-auth profile secrets may add only %s, not %s", strings.Join(OptionalSecrets, ", "), key)
		}
	}
	for _, key := range slices.Concat(Secrets, OptionalSecrets, optionalSecrets, []string{EnvListen, EnvBundleExtract}) {
		if _, set := env[key]; set {
			return fmt.Errorf("ts-auth profile must not set %s", key)
		}
	}
	for key, want := range map[string]string{EnvPublicOrigin: PublicOrigin(cell), EnvAPIURL: APIURL(cell), EnvDatabase: Database, EnvAudiences: APIURL(cell),
		EnvDashboardRedirectURIs: DashboardRedirectURI, EnvDashboardLogoutURIs: DashboardLogoutURI} {
		if env[key] != want {
			return fmt.Errorf("ts-auth profile must set %s=%s", key, want)
		}
	}
	return nil
}

// ValidateMembers checks a ts-auth profile's private TerraBase endpoints
// against the cell's TerraBase profile terraBase: each one is
// https://<member IP>:<client port> of a member TERRABASE_PEERS lists, at
// most once, and EnvAPICA holds 1 to 4 PEM CA certificates and nothing else.
// Several endpoints need EnvAPIFailover=true. A profile without endpoints and
// CA stores through EnvAPIURL. Without a terrabase
// profile, as in an identity-only controller config whose first cell spec
// brings it, only the pairing and the CA are checked.
func ValidateMembers(env, terraBase map[string]string) error {
	endpoints, roots := env[EnvAPIEndpoints], env[EnvAPICA]
	if endpoints == "" && roots == "" {
		return nil
	}
	if endpoints == "" || roots == "" {
		return fmt.Errorf("ts-auth profile sets %s and %s together", EnvAPIEndpoints, EnvAPICA)
	}
	if !caCertificates(roots) {
		return fmt.Errorf("%s must hold 1 to 4 PEM CA certificates and nothing else", EnvAPICA)
	}
	if failover, set := env[EnvAPIFailover]; set && failover != "true" && failover != "false" ||
		strings.Contains(endpoints, ";") && failover != "true" {
		return fmt.Errorf("%s lists several members only with %s=true", EnvAPIEndpoints, EnvAPIFailover)
	}
	if len(terraBase) == 0 {
		return nil
	}
	members, err := terrabase.ParseProfile(terraBase)
	if err != nil || members.ClientPort == 0 {
		return fmt.Errorf("%s needs a terrabase profile with %s", EnvAPIEndpoints, terrabase.EnvClientPort)
	}
	seen := map[string]bool{}
	for _, endpoint := range strings.Split(endpoints, ";") {
		member := slices.ContainsFunc(members.Peers, func(peer terrabase.Peer) bool {
			return endpoint == "https://"+netip.AddrPortFrom(peer.Address.Addr(), uint16(members.ClientPort)).String()
		})
		if !member || seen[endpoint] {
			return fmt.Errorf("%s must list distinct https://IP:%d client endpoints of the %s, not %q",
				EnvAPIEndpoints, members.ClientPort, terrabase.EnvPeers, endpoint)
		}
		seen[endpoint] = true
	}
	return nil
}

