type placementAdmissionTestControl struct {
	snapshot authority.Snapshot
	entries  map[string]authority.LogEntry
	terminal map[string]authority.LogEntry
	nextSeq  uint64
}

func newPlacementAdmissionControl() *placementAdmissionTestControl {
	return &placementAdmissionTestControl{
		snapshot: authority.Snapshot{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV", Scope: "gru", CandidateID: "0000000000GR3712FB1A87M2H7", Leader: true, Ready: true,
			Epoch: 3, Revision: 1, ExpiresAt: time.Now().Add(time.Minute)},
		entries:  make(map[string]authority.LogEntry),
		terminal: make(map[string]authority.LogEntry),
	}
}

func (control *placementAdmissionTestControl) Current() authority.Snapshot { return control.snapshot }

func (control *placementAdmissionTestControl) ReadPlacementIntent(_ context.Context, databaseID, partitionID string) (authority.LogEntry, error) {
	entry, exists := control.entries[databaseID+"."+partitionID]
	if !exists {
		return authority.LogEntry{}, authority.ErrNotFound
	}
	entry.Payload = bytes.Clone(entry.Payload)
	return entry, nil
}

func (control *placementAdmissionTestControl) ReadTerminalIntent(_ context.Context, databaseID, partitionID string) (authority.LogEntry, error) {
	entry, exists := control.terminal[databaseID+"."+partitionID]
	if !exists {
		return authority.LogEntry{}, authority.ErrNotFound
	}
	entry.Payload = bytes.Clone(entry.Payload)
	return entry, nil
}

func (*placementAdmissionTestControl) ReadManagedUpdate(context.Context, string, string) (authority.LogEntry, error) {
	return authority.LogEntry{}, authority.ErrNotFound
}

func (*placementAdmissionTestControl) ReadManagedUpdateOperation(context.Context, string, string, string) ([]authority.LogEntry, error) {
	return nil, authority.ErrNotFound
}

func (*placementAdmissionTestControl) ListManagedUpdates(context.Context, string, string) ([]authority.LogEntry, error) {
	return []authority.LogEntry{}, nil
}

func (control *placementAdmissionTestControl) ConfirmActivePlacementIntent(ctx context.Context, epoch uint64,
	databaseID, partitionID string, payload []byte,
) (uint64, error) {
	if epoch != control.snapshot.Epoch {
		return 0, authority.ErrFenced
	}
	if _, err := control.ReadTerminalIntent(ctx, databaseID, partitionID); err == nil {
		return 0, authority.ErrFenced
	} else if !errors.Is(err, authority.ErrNotFound) {
		return 0, err
	}
	entry, err := control.ReadPlacementIntent(ctx, databaseID, partitionID)
	if err != nil {
		return 0, err
	}
	if !bytes.Equal(entry.Payload, payload) {
		return 0, authority.ErrConflict
	}
	return entry.Sequence, nil
}

func (control *placementAdmissionTestControl) CommitPlacementIntent(
	_ context.Context,
	expectedEpoch uint64,
	databaseID string,
	partitionID string,
	operationID string,
	expectedSequence uint64,
	payload []byte,
) (uint64, error) {
	if expectedEpoch != control.snapshot.Epoch {
		return 0, authority.ErrFenced
	}
	key := databaseID + "." + partitionID
	current, exists := control.entries[key]
	if exists && current.Sequence != expectedSequence || !exists && expectedSequence != 0 {
		return 0, authority.ErrConflict
	}
	control.nextSeq++
	control.entries[key] = authority.LogEntry{
		Kind: authority.MutationPlacementIntent, SubjectKey: key, OperationID: operationID,
		Epoch: expectedEpoch, Sequence: control.nextSeq, CreatedAt: time.Now().UTC(), Payload: bytes.Clone(payload),
	}
	return control.nextSeq, nil
}

func (control *placementAdmissionTestControl) ListPlacementIntents(context.Context) ([]authority.LogEntry, error) {
	entries := make([]authority.LogEntry, 0, len(control.entries))
	for _, entry := range control.entries {
		entry.Payload = bytes.Clone(entry.Payload)
		entries = append(entries, entry)
	}
	return entries, nil
}

func verifyAndApplyPlacement(ctx context.Context, wire []byte, cell string, policy signerPolicy, control placementAdmissionControl, material ...placementMaterialAdmission) (placementApplyResponse, error) {
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(wire, &envelope, maxPlacementWireBytes); err != nil {
		return placementApplyResponse{}, err
	}
	var intent placement.Intent
	if err := protocol.DecodeStrict(envelope.Payload, &intent, maxPlacementIntentBytes); err != nil {
		return placementApplyResponse{}, err
	}
	if err := intent.ValidateForAdmission(); err != nil {
		return placementApplyResponse{}, err
	}
	if !intentSelectsCell(intent, cell) {
		return placementApplyResponse{}, errors.New("placement intent does not select this regional cell")
	}
	grant, exists := policy.grant(envelope.Actor)
	if !exists || !grant.CanPlaceTerraBase {
		return placementApplyResponse{}, errors.New("placement actor is unauthorized")
	}
	trusted, exists := policy.trusted(envelope.KeyID)
	if !exists || trusted.Actor != envelope.Actor {
		return placementApplyResponse{}, errors.New("placement signing key is untrusted")
	}
	if err := protocol.VerifyEnvelope(envelope, protocol.EnvelopeScope{
		Region: cell, Kind: managedKindPlacement, Actor: trusted.Actor,
		OperationID: placementOperationID(intent), Generation: intent.Generation, Epoch: envelope.Epoch,
	}, trusted.PublicKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: 5 * time.Minute, ClockSkew: 30 * time.Second}); err != nil {
		return placementApplyResponse{}, err
	}
	if envelope.Epoch == 0 || control.Current().Epoch != envelope.Epoch {
		return placementApplyResponse{}, authority.ErrFenced
	}
	payload, err := protocol.EncodeJSON(intent)
	if err != nil {
		return placementApplyResponse{}, err
	}
	if !bytes.Equal(envelope.Payload, payload) {
		return placementApplyResponse{}, errors.New("signed placement payload is not canonical")
	}
	if len(material) > 1 {
		return placementApplyResponse{}, errors.New("multiple managed material verifiers")
	}
	if len(material) == 1 {
		if material[0] == nil {
			return placementApplyResponse{}, errors.New("managed material verifier is unavailable")
		}
		if err := material[0](ctx, intent); err != nil {
			return placementApplyResponse{}, fmt.Errorf("verify committed managed material: %w", err)
		}
	}
	for range 8 {
		if _, err := control.ReadTerminalIntent(ctx, intent.DatabaseID, intent.PartitionID); err == nil {
			return placementApplyResponse{}, authority.ErrFenced
		} else if !errors.Is(err, authority.ErrNotFound) {
			return placementApplyResponse{}, err
		}
		current, err := control.ReadPlacementIntent(ctx, intent.DatabaseID, intent.PartitionID)
		if err == nil {
			old, err := placement.DecodeCommittedIntent(current.Payload)
			if err != nil || old.DatabaseID != intent.DatabaseID || old.PartitionID != intent.PartitionID {
				return placementApplyResponse{}, errors.New("durable placement intent is corrupt")
			}
			if old.Generation != intent.Generation || !bytes.Equal(current.Payload, payload) {
				return placementApplyResponse{}, authority.ErrConflict
			}
			sequence, err := control.ConfirmActivePlacementIntent(ctx, envelope.Epoch, intent.DatabaseID, intent.PartitionID, payload)
			if err != nil {
				return placementApplyResponse{}, err
			}
			return placementApplyResponse{DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID, Generation: intent.Generation, Sequence: sequence}, nil
		} else if !errors.Is(err, authority.ErrNotFound) {
			return placementApplyResponse{}, err
		}
		sequence, err := control.CommitPlacementIntent(ctx, envelope.Epoch, intent.DatabaseID, intent.PartitionID, placementOperationID(intent), 0, payload)
		if err == nil {
			return placementApplyResponse{DatabaseID: intent.DatabaseID, PartitionID: intent.PartitionID, Generation: intent.Generation, Sequence: sequence}, nil
		}
		if !errors.Is(err, authority.ErrConflict) {
			return placementApplyResponse{}, err
		}
	}
	return placementApplyResponse{}, errors.New("placement intent contention")
}

func (intent Intent) Validate() error {
	if intent.SchemaVersion != IntentSchemaVersion ||
		!entityid.Valid(intent.DatabaseID) ||
		!entityid.Valid(intent.PartitionID) || intent.Generation == 0 ||
		len(intent.ActiveRegions) < 1 || len(intent.ActiveRegions) > len(regionsInOrder) {
		return fmt.Errorf("%w: schema, identity, generation or region count", ErrInvalidIntent)
	}
	for index, region := range intent.ActiveRegions {
		if !knownRegion(region) {
			return fmt.Errorf("%w: unsupported region %q", ErrInvalidIntent, region)
		}
		if slices.Contains(intent.ActiveRegions[:index], region) {
			return fmt.Errorf("%w: repeated region %q", ErrInvalidIntent, region)
		}
	}
	if !canonicalRegions(intent.ActiveRegions) || len(intent.ManagedHostProfiles) != len(intent.ActiveRegions) {
		return fmt.Errorf("%w: managed profiles must exactly cover canonically ordered selected regions", ErrInvalidIntent)
	}
	for index, profile := range intent.ManagedHostProfiles {
		if profile.Region != intent.ActiveRegions[index] {
			return fmt.Errorf("%w: managed profiles are missing, foreign or out of canonical order", ErrInvalidIntent)
		}
		if err := profile.Validate(); err != nil {
			return err
		}
	}
	if err := intent.CanonicalRoster.Validate(intent.ActiveRegions); err != nil {
		return err
	}
	if len(intent.RuntimeManifests) != len(intent.CanonicalRoster.Rows) {
		return fmt.Errorf("%w: runtime manifests must cover every canonical roster seat", ErrInvalidIntent)
	}
	uuids := make(map[string]struct{}, len(intent.RuntimeManifests))
	for index, manifest := range intent.RuntimeManifests {
		row := intent.CanonicalRoster.Rows[index]
		if err := manifest.Validate(); err != nil {
			return err
		}
		if manifest.Region != row.Region || manifest.SeatID != row.SeatID ||
			manifest.TrustedKeySHA256 != intent.CanonicalRoster.Authority.TrustedKeySHA256 ||
			manifest.ReplicationPeerMemberID == row.MemberID {
			return fmt.Errorf("%w: runtime manifest does not match canonical roster seat", ErrInvalidIntent)
		}
		if manifest.ReplicationPeerMemberID != "" && !slices.ContainsFunc(intent.CanonicalRoster.Rows, func(peer CanonicalRosterRow) bool {
			return peer.MemberID == manifest.ReplicationPeerMemberID
		}) {
			return fmt.Errorf("%w: runtime peer is outside the signed roster", ErrInvalidIntent)
		}
		if _, exists := uuids[manifest.FileSystemUUID]; exists {
			return fmt.Errorf("%w: duplicate runtime filesystem UUID", ErrInvalidIntent)
		}
		uuids[manifest.FileSystemUUID] = struct{}{}
	}
	return nil
}

// ValidateForAdmission limits newly signed managed placements to schema 5.
// Only the current schema is accepted.
func (intent Intent) ValidateForAdmission() error {
	if intent.SchemaVersion != IntentSchemaVersion {
		return fmt.Errorf("%w: schema %d is historical and cannot authorize a new managed placement", ErrInvalidIntent, intent.SchemaVersion)
	}
	return intent.Validate()
}

func (intent Intent) RosterRowForSeat(seat Seat) (CanonicalRosterRow, error) {
	if err := intent.ValidateForAdmission(); err != nil {
		return CanonicalRosterRow{}, err
	}
	for _, row := range intent.CanonicalRoster.Rows {
		if row.Region != seat.Region || row.SeatID != seat.MemberID {
			continue
		}
		if row.FailureDomain != seat.FailureDomain || seatIDForKind(row.Region, seat.Kind) != seat.MemberID {
			return CanonicalRosterRow{}, fmt.Errorf("%w: roster row does not match the configured placement seat", ErrInvalidIntent)
		}
		return row, nil
	}
	return CanonicalRosterRow{}, fmt.Errorf("%w: no canonical roster row for region %s seat %s", ErrInvalidIntent, seat.Region, seat.MemberID)

