type placementSizingProvider struct {
	oci.Provider
	config         oci.RegionConfig
	instance       oci.CloudInstance
	bootInstanceID string
	bootVolume     oci.CloudBootVolume
	launches       []oci.LaunchRequest
}

func (p *placementSizingProvider) ListInstances(_ context.Context, compartmentID string) ([]oci.CloudInstance, error) {
	if compartmentID != p.config.CompartmentID {
		return nil, oci.ErrForeignResource
	}
	if p.instance.ID == "" {
		return nil, nil
	}
	instance := p.instance
	instance.FreeformTags = maps.Clone(instance.FreeformTags)
	instance.Metadata = maps.Clone(instance.Metadata)
	return []oci.CloudInstance{instance}, nil
}

func (p *placementSizingProvider) GetInstance(_ context.Context, instanceID string) (oci.CloudInstance, error) {
	if p.instance.ID != instanceID || instanceID == "" {
		return oci.CloudInstance{}, errors.New("unknown fake OCI instance")
	}
	instance := p.instance
	instance.FreeformTags = maps.Clone(instance.FreeformTags)
	instance.Metadata = maps.Clone(instance.Metadata)
	return instance, nil
}

func (p *placementSizingProvider) LaunchInstance(_ context.Context, request oci.LaunchRequest) (oci.CloudInstance, error) {
	if p.instance.ID != "" {
		return oci.CloudInstance{}, errors.New("unexpected second fake OCI launch")
	}
	request.FreeformTags = maps.Clone(request.FreeformTags)
	p.launches = append(p.launches, request)
	p.instance = oci.CloudInstance{
		ID: "ocid1.instance.oc1..placement-sized", CompartmentID: p.config.CompartmentID,
		PrivateIP:          request.PrivateIP,
		AvailabilityDomain: p.config.AvailabilityDomain, FaultDomain: request.FaultDomain,
		Shape: request.Shape, Ocpus: new(float32(request.WholeOCPUs)),
		MemoryInGBs: new(float32(request.MemoryInGBs)), LifecycleState: "PROVISIONING", ETag: "etag-1",
		ImageID: p.config.ImageID, ConsistentVolumeNamingEnabled: new(true),
		Metadata:     map[string]string{hostboot.MetadataKey: request.BootDescriptor, "terrascale_host_node": request.Node},
		FreeformTags: maps.Clone(request.FreeformTags),
	}
	if err := p.bindBootVolume(p.instance.ID); err != nil {
		return oci.CloudInstance{}, err
	}
	return p.instance, nil
}

func (p *placementSizingProvider) bindBootVolume(instanceID string) error {
	if instanceID == "" || p.instance.ID != instanceID || len(p.launches) != 1 {
		return errors.New("fake OCI boot volume requires its one launched instance")
	}
	suffix, ok := strings.CutPrefix(instanceID, "ocid1.instance.")
	if !ok || suffix == "" {
		return errors.New("fake OCI instance has no valid boot-volume identity")
	}
	p.bootInstanceID = instanceID
	p.bootVolume = oci.CloudBootVolume{
		ID: "ocid1.bootvolume." + suffix, CompartmentID: p.config.CompartmentID,
		AvailabilityDomain: p.config.AvailabilityDomain, ImageID: p.config.ImageID,
		SizeGB: int64(p.config.BootVolumeGB), VPUsPerGB: int64(p.config.BootVolumeVPUsPerGB),
		LifecycleState: "AVAILABLE", ETag: "boot-etag-1",
	}
	return nil
}

func (p *placementSizingProvider) GetAttachedBootVolume(_ context.Context, instanceID string) (oci.CloudBootVolume, error) {
	if instanceID == "" || p.instance.ID != instanceID || p.bootInstanceID != instanceID ||
		p.bootVolume.ID == "" {
		return oci.CloudBootVolume{}, errors.New("unknown fake OCI boot attachment")
	}
	return p.bootVolume, nil
}

func (p *placementSizingProvider) ListVolumeAttachments(_ context.Context, compartmentID, instanceID string) ([]oci.CloudAttachment, error) {
	if compartmentID != p.config.CompartmentID || instanceID != p.instance.ID {
		return nil, oci.ErrForeignResource
	}
	return nil, nil
}

func launchPermanentSeat(t *testing.T, owner string, generation uint64) oci.LaunchRequest {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 30*time.Second)
	defer cancel()
	broker, err := newAuthenticatedNATS(t, "gru").start(t, ctx, natscell.Config{
		Cell: "gru", Instance: "placement-release", Replicas: 1,
		Embedded: &natscell.Embedded{Host: "127.0.0.1", Port: -1, StoreDir: filepath.Join(t.TempDir(), "nats")},
	})
	if err != nil {
		t.Fatal(err)
	}
	defer broker.Close()
	policy, privateKey := newPlacementAdmissionPolicy(t)
	control := newPlacementAdmissionControl()
	intent := testManagedPlacementIntent()
	if _, err := verifyAndApplyPlacement(ctx, signedPlacementEnvelope(t, intent, privateKey, protocol.EncodeJSON), "gru", policy, control); err != nil {
		t.Fatal(err)
	}
	reader := admittedPlacementReader{cell: "gru", store: control}
	committed, err := reader.ListPlacementIntents(ctx, "gru")
	if err != nil || len(committed) != 1 {
		t.Fatalf("admitted intents=%+v err=%v", committed, err)
	}
	profile, err := committed[0].ManagedHostProfile(oci.RegionGRU)
	if err != nil {
		t.Fatal(err)
	}
	store, err := placement.NewJetStreamStore(ctx, broker.JetStream(), "gru", 1, reader)
	if err != nil {
		t.Fatal(err)
	}
	journal, err := oci.OpenJournal(ctx, broker.JetStream(), 1)
	if err != nil {
		t.Fatal(err)
	}
	regionIntent := oci.RegionIntent{
		SchemaVersion: 1, Generation: generation, BootstrapRegion: oci.RegionGRU,
		Regions: []oci.RegionMapping{{Cell: oci.RegionGRU, OCIRegion: "sa-saopaulo-1"}},
	}
	regionConfig := oci.RegionConfig{
		Region: oci.RegionGRU, Generation: generation, Endpoint: "https://iaas.sa-saopaulo-1.oraclecloud.com",
		CompartmentID: "ocid1.compartment.oc1..owned", ImageCompartmentID: "ocid1.compartment.oc1..image", AvailabilityDomain: "AD-1",
		FaultDomains: []string{"FAULT-DOMAIN-1", "FAULT-DOMAIN-2"},
		SubnetID:     "ocid1.subnet.oc1..owned", ImageID: "ocid1.image.oc1..owned",
		NetworkSecurityGroupIDs: []string{"ocid1.networksecuritygroup.oc1..owned"},
		BootVolumeGB:            50, BootVolumeVPUsPerGB: 10, DataVolumeVPUsPerGB: 10, MaxDataVolumeGB: 50,
		Shape: profile.Compute.Shape, Owner: owner,
	}
	provider := &placementSizingProvider{config: regionConfig}
	fencer := placementSizingFencer{control: control}
	fleet, err := oci.NewFleetWithImageVerifier(regionConfig, regionIntent, provider, journal, fencer, nil, nil, acceptingImageVerifier{})
	if err != nil {
		t.Fatal(err)
	}
	controller, err := placement.StartController(ctx, placement.Config{
		Cell: "gru", Region: oci.RegionGRU, FaultDomains: regionConfig.FaultDomains,
		ManagedOwner: owner, FleetGeneration: generation, ImageID: regionConfig.ImageID,
		Environment: "production", MemberRole: "terrabase",
		Resources: placement.Resources{CPU: 1, MemoryBytes: 1 << 30, DiskBytes: 32 << 30},
	}, store, fencer, fleet, placementSizingHosts{}, placementSizingHosts{}, testPlacementAdmittedArtifact(intent))
	if err != nil {
		t.Fatal(err)
	}
	for range 2 {
		if err := controller.Tick(ctx); err != nil {
			t.Fatal(err)
		}
	}
	if len(provider.launches) != 1 {
		t.Fatalf("provider launches = %d, want one", len(provider.launches))
	}
	return provider.launches[0]
}

func NewJetStreamStore(ctx context.Context, js jetstream.JetStream, cell string, replicas int, intents AdmittedIntentReader) (Store, error) {
	if !validToken(cell) || js == nil || intents == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("placement store requires cell, JetStream, admitted intent reader and valid replica count")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket:       stateBucketName,
		Description:  "Durable regional TerraBase placement member state",
		History:      2,
		MaxValueSize: maxStateBytes,
		MaxBytes:     128 << 20,
		Storage:      jetstream.FileStorage,
		Replicas:     replicas,
	})
	if err != nil {
		return nil, fmt.Errorf("open placement member state: %w", err)
	}
	status, err := kv.Status(ctx)
	if err != nil {
		return nil, fmt.Errorf("read placement member state status: %w", err)
	}
	if status.Config().Replicas != replicas {
		return nil, fmt.Errorf("placement state has %d replicas, requires %d", status.Config().Replicas, replicas)
	}
	return &jetStreamStore{cell: cell, state: kv, intents: intents}, nil
}

func (store *jetStreamStore) ListIntents(ctx context.Context) ([]Intent, error) {
	intents, err := store.intents.ListPlacementIntents(ctx, store.cell)
	if err != nil {
		return nil, err
	}
	if len(intents) > maxIntentCount {
		return nil, errors.New("placement intent listing exceeds its bound")
	}
	seen := make(map[string]struct{}, len(intents))
	for _, intent := range intents {
		if err := intent.Validate(); err != nil {
			return nil, err
		}
		if !validLowerSHA256Digest(intent.PayloadDigest()) {
			return nil, fmt.Errorf("%w: admitted placement intent is missing its canonical committed payload digest", ErrInvalidIntent)
		}
		identity := intent.DatabaseID + "\x00" + intent.PartitionID
		if _, exists := seen[identity]; exists {
			return nil, fmt.Errorf("%w: duplicate database/partition intent %q/%q", ErrInvalidIntent, intent.DatabaseID, intent.PartitionID)
		}
		seen[identity] = struct{}{}
	}
	slices.SortFunc(intents, func(a, b Intent) int {
		if database := strings.Compare(a.DatabaseID, b.DatabaseID); database != 0 {
			return database
		}
		return strings.Compare(a.PartitionID, b.PartitionID)
	})
	return intents, nil
}

func (store *jetStreamStore) ReadTerminalIntent(ctx context.Context, databaseID, partitionID string) (authority.LogEntry, error) {
	return store.intents.ReadTerminalIntent(ctx, databaseID, partitionID)
}

func (store *jetStreamStore) ListMembers(ctx context.Context, databaseID, partitionID string) ([]VersionedMemberState, error) {
	if !validDatabaseKeyID(databaseID) || !entityid.Valid(partitionID) {
		return nil, fmt.Errorf("%w: database or partition id", ErrInvalidIntent)
	}
	// Every supported region has exactly two fixed seats in this schema.
	result := make([]VersionedMemberState, 0, len(regionsInOrder)*SeatsPerRegion)
	for _, region := range regionsInOrder {
		seats, err := RegionSeatIDs(region)
		if err != nil {
			return nil, err
		}
		for _, seat := range seats {
			member, err := store.ReadMember(ctx, databaseID, partitionID, seat)
			if errors.Is(err, ErrMemberNotFound) {
				continue
			}
			if err != nil {
				return nil, err
			}
			result = append(result, member)
		}
	}
	slices.SortFunc(result, func(a, b VersionedMemberState) int {
		return strings.Compare(a.State.MemberID, b.State.MemberID)
	})
	return result, nil
}

func (store *jetStreamStore) ReadMember(ctx context.Context, databaseID, partitionID, seatID string) (VersionedMemberState, error) {
	if !validDatabaseKeyID(databaseID) || !entityid.Valid(partitionID) ||
		!entityid.Valid(seatID) {
		return VersionedMemberState{}, fmt.Errorf("%w: database, partition, or seat id", ErrInvalidIntent)
	}
	key := memberStateKey(databaseID, partitionID, seatID)
	entry, err := store.state.Get(ctx, key)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return VersionedMemberState{}, ErrMemberNotFound
	}
	if err != nil {
		return VersionedMemberState{}, err
	}
	if entry.Operation() != jetstream.KeyValuePut {
		return VersionedMemberState{}, fmt.Errorf("%w: tombstone at %s", ErrStoreCorrupt, key)
	}
	return decodeMemberState(databaseID, partitionID, seatID, entry.Value(), entry.Revision())
}

func decodeMemberState(databaseID, partitionID, seatID string, data []byte, revision uint64) (VersionedMemberState, error) {
	key := memberStateKey(databaseID, partitionID, seatID)
	var state MemberState
	if len(data) > maxStateBytes || json.Unmarshal(data, &state, json.RejectUnknownMembers(true)) != nil {
		return VersionedMemberState{}, fmt.Errorf("%w: decode %s", ErrStoreCorrupt, key)
	}
	if err := state.Validate(); err != nil || state.DatabaseID != databaseID || state.PartitionID != partitionID ||
		state.MemberID != seatID || memberStateKey(state.DatabaseID, state.PartitionID, state.MemberID) != key {
		return VersionedMemberState{}, fmt.Errorf("%w: invalid state at %s", ErrStoreCorrupt, key)
	}
	return VersionedMemberState{State: state, Revision: revision}, nil
}

func (store *jetStreamStore) CompareAndSwap(ctx context.Context, expected uint64, state MemberState) (uint64, error) {
	if err := state.Validate(); err != nil {
		return 0, err
	}
	data, err := json.Marshal(state)
	if err != nil {
		return 0, err
	}
	if len(data) > maxStateBytes {
		return 0, errors.New("placement member state exceeds size bound")
	}
	key := memberStateKey(state.DatabaseID, state.PartitionID, state.MemberID)
	var revision uint64
	if expected == 0 {
		revision, err = store.state.Create(ctx, key, data)
	} else {
		revision, err = store.state.Update(ctx, key, data, expected)
	}
	if err != nil {
		if errors.Is(err, jetstream.ErrKeyExists) || errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
			return 0, fmt.Errorf("%w: %v", ErrStoreConflict, err)
		}
		return 0, err
	}
	return revision, nil
}

func StartController(ctx context.Context, config Config, store Store, fencer authority.Fencer, fleet oci.Fleet, hosts HostView, desired DesiredWriter, resolveArtifact ArtifactResolver) (*Controller, error) {
	if ctx == nil || ctx.Err() != nil {
		return nil, errors.New("placement controller requires a live context")
	}
	if err := config.validate(); err != nil {
		return nil, err
	}
	if store == nil || fencer == nil || fleet == nil || hosts == nil || desired == nil || resolveArtifact == nil {
		return nil, errors.New("placement controller requires durable state, authority, OCI fleet, host view, desired writer and artifact admission")
	}
	if fleet.Region() != config.Region {
		return nil, errors.New("placement controller region differs from its pinned OCI fleet")
	}
	if config.TickInterval == 0 {
		config.TickInterval = defaultTickInterval
	}
	return &Controller{config: config, store: store, fencer: fencer, fleet: fleet, hosts: hosts, desired: desired, resolveArtifact: resolveArtifact}, nil
}

func (config Config) validate() error {
	if !validToken(config.Cell) || !knownRegion(config.Region) || !validToken(config.ManagedOwner) ||
		!validToken(config.Environment) || !validToken(config.MemberRole) || config.FleetGeneration == 0 ||
		!strings.HasPrefix(config.ImageID, "ocid1.image.") || len(config.ImageID) > 255 || strings.ContainsAny(config.ImageID, " \t\r\n") ||
		!positive(config.Resources) ||
		config.Resources.CPU > 4096 || config.Resources.MemoryBytes > 1<<50 || config.Resources.DiskBytes > 1<<50 {
		return errors.New("placement controller config has an invalid cell, region, owner, role, or resource profile")
	}
	if err := config.VolumeDeadlines.Validate(); err != nil {
		return err
	}
	if config.LostMemberGrace < 0 || config.LostMemberGrace > 7*24*time.Hour {
		return errors.New("placement lost member grace must be between zero and seven days")
	}
	if config.TickInterval < 0 || config.TickInterval != 0 && (config.TickInterval < minTickInterval || config.TickInterval > maxTickInterval) {
		return errors.New("placement tick interval must be zero or between 100ms and 5m")
	}
	if len(config.FaultDomains) < 2 || len(config.FaultDomains) > 3 || config.FaultDomains[0] == config.FaultDomains[1] {
		return errors.New("placement region requires at least two distinct OCI fault domains")
	}
	for _, domain := range config.FaultDomains {
		if len(domain) != len("FAULT-DOMAIN-1") || !strings.HasPrefix(domain, "FAULT-DOMAIN-") || domain[len(domain)-1] < '1' || domain[len(domain)-1] > '3' {
			return fmt.Errorf("invalid configured OCI fault domain %q", domain)
		}
	}
	return nil
}

func (controller *Controller) Tick(ctx context.Context) error {
	if controller == nil || ctx == nil {
		return errors.New("placement controller and context are required")
	}
	if err := ctx.Err(); err != nil {
		return err
	}
	snapshot := controller.fencer.Current()
	if !snapshot.CanMutate() {
		return nil
	}
	epoch := snapshot.Epoch
	intents, err := controller.store.ListIntents(ctx)
	if err != nil {
		return err
	}
	if len(intents) > maxIntentCount {
		return errors.New("placement intent list exceeds its safety bound")
	}
	instances, err := controller.fleet.Observe(oci.WithCachedVerification(ctx))
	if err != nil {
		return fmt.Errorf("observe region-bound OCI fleet: %w", err)
	}
	instanceByID := make(map[string]oci.Instance, len(instances))
	for _, instance := range instances {
		if instance.ID == "" || instance.Node == "" || instance.Region != controller.config.Region || instance.ETag == "" {
			return errors.New("OCI fleet returned an incomplete or cross-region instance")
		}
		if _, exists := instanceByID[instance.ID]; exists {
			return fmt.Errorf("OCI fleet returned duplicate instance %q", instance.ID)
		}
		instanceByID[instance.ID] = instance
	}
	statuses, err := controller.hosts.ListHosts(ctx)
	if err != nil {
		return fmt.Errorf("read current host registrations and reports: %w", err)
	}
	statusByNode := make(map[string]host.HostStatus, len(statuses))
	for _, status := range statuses {
		node := status.Registration.Node
		if node == "" {
			return errors.New("host view returned a registration without a node")
		}
		if _, exists := statusByNode[node]; exists {
			return fmt.Errorf("host view returned duplicate node %q", node)
		}
		statusByNode[node] = status
	}
	seenIntents := make(map[string]struct{}, len(intents))
	// A failing placement must not starve independent ones: its error is
	// reported with the pass while later placements still advance.
	var placementErrs []error
intents:
	for _, intent := range intents {
		if err := intent.Validate(); err != nil {
			return err
		}
		identity := intent.DatabaseID + "\x00" + intent.PartitionID
		if _, exists := seenIntents[identity]; exists {
			return fmt.Errorf("%w: duplicate database/partition intent", ErrInvalidIntent)
		}
		seenIntents[identity] = struct{}{}
		if _, err := controller.store.ReadTerminalIntent(ctx, intent.DatabaseID, intent.PartitionID); err == nil {
			controller.hold(fmt.Sprintf("database %s/%s has a committed terminal teardown fence", intent.DatabaseID, intent.PartitionID))
			continue
		} else if !errors.Is(err, authority.ErrNotFound) {
			return fmt.Errorf("read terminal workload fence for %s/%s: %w", intent.DatabaseID, intent.PartitionID, err)
		}
		if intent.SchemaVersion != IntentSchemaVersion || intent.PayloadDigest() == "" {
			controller.hold(fmt.Sprintf("database %s/%s has no admitted managed placement profile; host reconciliation is held", intent.DatabaseID, intent.PartitionID))
			continue
		}
		if len(intent.ActiveRegions) != 1 {
			controller.hold(fmt.Sprintf("database %s/%s has %d regions; current TerraBase outbound sender supports exactly two members in one region", intent.DatabaseID, intent.PartitionID, len(intent.ActiveRegions)))
			continue
		}
		members, err := controller.store.ListMembers(ctx, intent.DatabaseID, intent.PartitionID)
		if err != nil {
			return err
		}
		if len(members) > maxMemberStates {
			return fmt.Errorf("placement member state for %s/%s exceeds its bound", intent.DatabaseID, intent.PartitionID)
		}
		if !slices.Contains(intent.ActiveRegions, controller.config.Region) {
			if len(members) > 0 && controller.config.OnHold != nil {
				controller.config.OnHold(fmt.Sprintf("database %s/%s regional retirement is held; trusted replication, quorum, drain, writer-stop, and retained-volume evidence is required", intent.DatabaseID, intent.PartitionID))
			}
			continue
		}
		seats, err := controller.localSeats(intent)
		if err != nil {
			return err
		}
		rosterDigest, err := intent.CanonicalRosterDigest()
		if err != nil {
			return err
		}
		rowsBySeat := make(map[string]CanonicalRosterRow, len(seats))
		manifestsBySeat := make(map[string]RuntimeManifest, len(seats))
		manifestDigestsBySeat := make(map[string]string, len(seats))
		rosterHeld := false
		for _, seat := range seats {
			row, err := intent.RosterRowForSeat(seat)
			if err != nil {
				controller.hold(fmt.Sprintf("member %s has no signed roster row matching its configured seat; host reconciliation is held: %v", seat.MemberID, err))
				rosterHeld = true
				break
			}
			rowsBySeat[seat.MemberID] = row
			manifest, err := intent.RuntimeManifestForSeat(seat)
			if err != nil {
				controller.hold(fmt.Sprintf("member %s has no signed runtime manifest: %v", seat.MemberID, err))
				rosterHeld = true
				break
			}
			manifestDigest, err := manifest.Digest()
			if err != nil {
				return err
			}
			manifestsBySeat[seat.MemberID] = manifest
			manifestDigestsBySeat[seat.MemberID] = manifestDigest
		}
		if rosterHeld {
			continue
		}
		profile, err := intent.ManagedHostProfile(controller.config.Region)
		if err != nil {
			return err
		}
		profileDigest, err := profile.ProfileDigest()
		if err != nil {
			return err
		}
		memberByID := make(map[string]VersionedMemberState, len(members))
		for _, member := range members {
			if member.State.DatabaseID != intent.DatabaseID || member.State.PartitionID != intent.PartitionID {
				return fmt.Errorf("%w: member state escaped database/partition scope", ErrStoreCorrupt)
			}
			if _, exists := memberByID[member.State.MemberID]; exists {
				return fmt.Errorf("%w: duplicate member state %q", ErrStoreCorrupt, member.State.MemberID)
			}
			memberByID[member.State.MemberID] = member
		}
		held := false
		for _, seat := range seats {
			versioned, exists := memberByID[seat.MemberID]
			if !exists {
				continue
			}
			state := versioned.State
			if state.Region != seat.Region || state.Kind != seat.Kind || state.FailureDomain != seat.FailureDomain {
				return fmt.Errorf("%w: admitted placement seat conflicts with durable member identity", ErrStoreCorrupt)
			}
			if state.SchemaVersion != managedUpdateMemberStateSchemaVersion ||
				state.CanonicalRosterRow != rowsBySeat[seat.MemberID] ||
				state.RuntimeManifest != manifestsBySeat[seat.MemberID] ||
				state.RuntimeManifestDigest != manifestDigestsBySeat[seat.MemberID] ||
				state.CanonicalRosterDigest != rosterDigest ||
				state.AuthorityReference != intent.CanonicalRoster.Authority ||
				state.IntentPayloadDigest == "" || state.ManagedHostProfileDigest == "" ||
				state.IntentPayloadDigest != intent.PayloadDigest() || state.ManagedHostProfile != profile ||
				state.ManagedHostProfileDigest != profileDigest || state.IntentGeneration != intent.Generation {
				controller.hold(fmt.Sprintf("member %s has no matching immutable roster, authority reference, or placement profile; an explicit new attempt is required", seat.MemberID))
				held = true
				break
			}
			if state.Stage == StageRemoved {
				controller.hold(fmt.Sprintf("removed member %s requires an explicit reconciled new attempt", seat.MemberID))
				held = true
				break
			}
		}
		if held {
			continue
		}
		managedUpdateActed, err := controller.reconcileManagedUpdate(ctx, epoch, intent, seats, memberByID)
		if err != nil {
			placementErrs = append(placementErrs, fmt.Errorf("%s/%s: %w", intent.DatabaseID, intent.PartitionID, err))
			continue
		}
		if managedUpdateActed {
			return errors.Join(placementErrs...)
		}
		for _, seat := range seats {
			versioned, exists := memberByID[seat.MemberID]
			if !exists {
				state := controller.initialState(intent, seat, rowsBySeat[seat.MemberID], rosterDigest,
					profile, profileDigest, manifestsBySeat[seat.MemberID], manifestDigestsBySeat[seat.MemberID], 1)
				if _, err := controller.persist(ctx, epoch, 0, state); err != nil {
					return errors.Join(append(placementErrs, err)...)
				}
				return errors.Join(placementErrs...)
			}
			acted, err := controller.replaceLostMember(ctx, epoch, intent, seat, versioned, seats, memberByID,
				instanceByID, statusByNode)
			if err != nil {
				placementErrs = append(placementErrs, fmt.Errorf("%s/%s: %w", intent.DatabaseID, intent.PartitionID, err))
				continue intents
			}
			if acted {
				return errors.Join(placementErrs...)
			}
			acted, err = controller.advanceMember(ctx, epoch, intent, seat, versioned, instanceByID, statusByNode)
			if err != nil {
				placementErrs = append(placementErrs, fmt.Errorf("%s/%s: %w", intent.DatabaseID, intent.PartitionID, err))
				continue intents
			}
			if acted {
				return errors.Join(placementErrs...)
			}
		}
	}
	return errors.Join(placementErrs...)
}

func (controller *Controller) advanceMember(
	ctx context.Context,
	epoch uint64,
	intent Intent,
	seat Seat,
	versioned VersionedMemberState,
	instances map[string]oci.Instance,
	statuses map[string]host.HostStatus,
) (bool, error) {
	state := versioned.State
	if state.ManagedRuntimeTarget.Phase == ManagedUpdateSeatHeld {
		controller.hold(fmt.Sprintf("managed update %s is durably held: %s",
			state.ManagedRuntimeTarget.OperationID, state.ManagedRuntimeTarget.Outcome))
		return false, nil
	}
	switch state.Stage {
	case StagePreparedHost:
		if !controller.runtimeArtifactReady(ctx, state, seat) {
			return false, nil
		}
		if err := controller.guard(ctx, epoch); err != nil {
			return false, err
		}
		instance, err := controller.fleet.EnsureHost(ctx, pinnedEnsureRequest(state))
		if err != nil {
			return false, fmt.Errorf("ensure TerraBase member host %s/%s: %w", intent.DatabaseID, seat.MemberID, err)
		}
		if err := controller.validateEnsuredInstance(instance, state, seat); err != nil {
			return false, err
		}
		state.Stage = StageAwaitingHost
		state.HostNode = instance.Node
		state.InstanceID = instance.ID
		state.InstanceETag = instance.ETag
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "host")
		_, err = controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err
	case StageAwaitingHost:
		instance, exists := instances[state.InstanceID]
		if !exists {
			// Retrying EnsureHost with the same durable create key recovers an
			// unknown launch outcome without adopting a tag-matched resource.
			if !controller.runtimeArtifactReady(ctx, state, seat) {
				return false, nil
			}
			if err := controller.guard(ctx, epoch); err != nil {
				return false, err
			}
			instance, err := controller.fleet.EnsureHost(ctx, pinnedEnsureRequest(state))
			if err != nil {
				return false, fmt.Errorf("recover TerraBase member host %s/%s: %w", intent.DatabaseID, seat.MemberID, err)
			}
			if err := controller.validateEnsuredInstance(instance, state, seat); err != nil {
				return false, err
			}
			state.HostNode, state.InstanceID, state.InstanceETag = instance.Node, instance.ID, instance.ETag
			_, err = controller.persist(ctx, epoch, versioned.Revision, state)
			return true, err
		}
		if err := controller.validateObservedInstance(instance, state, seat); err != nil {
			return false, err
		}
		status, admitted := controller.admittedHost(intent, state, instance, statuses)
		if !admitted {
			return false, nil
		}
		if state.VolumeID == "" {
			state.Stage = StagePreparedVolume
		} else {
			state.Stage = StagePreparedAttach
		}
		state.HostGeneration = status.Registration.Generation
		state.InstanceETag = instance.ETag
		state.OperationID = memberOperationID(intent, seat.MemberID, state.HostAttempt, "admitted")
		_, err := controller.persist(ctx, epoch, versioned.Revision, state)
		return true, err

func pinnedEnsureRequest(state MemberState) oci.EnsureRequest {
	privateIP, _, _ := net.SplitHostPort(state.RuntimeManifest.ReplicationListenAddress)
	// The fleet rejects an empty name, so an unnamed seat fails closed there.
	name, _ := seatMemberName(state.Region, state.MemberID)
	return oci.EnsureRequest{
		Name: name, CreateKey: state.CreateKey, PrivateIP: privateIP, FaultDomain: state.FailureDomain,
		Shape: state.ManagedHostProfile.Compute.Shape, WholeOCPUs: state.ManagedHostProfile.Compute.WholeOCPUs,
		MemoryInGBs:            state.ManagedHostProfile.Compute.MemoryInGBs,
		PlacementProfileDigest: state.ManagedHostProfileDigest, PlacementGeneration: state.IntentGeneration,
		BootPins: oci.HostBootPins{
			DatabaseID: state.DatabaseID, PartitionID: state.PartitionID, SeatID: state.MemberID,
			HostAttempt: state.HostAttempt, IntentPayloadDigest: state.IntentPayloadDigest,
			CanonicalRosterDigest: state.CanonicalRosterDigest, RuntimeManifestDigest: state.RuntimeManifestDigest,
		},
	}
}

func NewFleetWithImageVerifier(
	config RegionConfig,
	intent RegionIntent,
	provider Provider,
	journal Journal,
	fencer authority.Fencer,
	drainRequester DrainRequester,
	writerStop WriterStopVerifier,
	imageVerifier ImageQualificationVerifier,
) (Fleet, error) {
	return newFleet(config, intent, provider, journal, fencer, drainRequester, writerStop, imageVerifier)
}

func newFleet(
	config RegionConfig,
	intent RegionIntent,
	provider Provider,
	journal Journal,
	fencer authority.Fencer,
	drainRequester DrainRequester,
	writerStop WriterStopVerifier,
	imageVerifier ImageQualificationVerifier,
) (Fleet, error) {
	if err := config.Validate(intent); err != nil {
		return nil, err
	}
	if provider == nil || journal == nil || fencer == nil {
		return nil, errors.New("OCI fleet requires a provider, durable journal, and authority fencer")
	}
	return &fleet{
		config: config, provider: provider, journal: journal, fencer: fencer,
		drainRequester: drainRequester, writerStop: writerStop, imageVerifier: imageVerifier, now: time.Now,
		attachmentSettle: attachmentSettleTimeout,
	}, nil
}

// NewInstancePrincipalFleetWithImageVerifier builds official OCI Compute and
// Block Volume SDK clients using instance-principal authentication for one

func (f *fleet) observe(ctx context.Context, selectInstance func(id, node string) bool) ([]Instance, error) {
	cloudInstances, err := f.provider.ListInstances(ctx, f.config.CompartmentID)
	if err != nil {
		return nil, err
	}
	if len(cloudInstances) > maxFleetInstances {
		return nil, errors.New("OCI member host list exceeds its safety bound")
	}
	// A complete sweep also counts the fleet by lifecycle state for the
	// dashboard; the tally never changes what the sweep returns.
	var tally *inventoryTally
	if selectInstance == nil {
		tally = newInventoryTally()
		ctx = withInventoryTally(ctx, tally)
	}
	instances := make([]Instance, 0, len(cloudInstances))
	for _, listed := range cloudInstances {
		tags := listed.FreeformTags
		if tags[tagManagedBy] != managedByValue || tags[tagOwner] != f.config.Owner {
			continue
		}
		createKey := tags[tagCreateKey]
		if tags[tagRegion] != string(f.config.Region) || tags[tagGeneration] != fmt.Sprint(f.config.Generation) ||
			tags[tagResource] != resourceMemberHost || !validCreateKey(createKey) || tags[tagHostNode] != hostNode(f.config, createKey) {
			slog.WarnContext(ctx, "withholding OCI instance with out-of-scope identity tags", "instance_id", listed.ID, "region", f.config.Region)
			continue
		}
		tally.instance(listed.LifecycleState)
		if selectInstance != nil && !selectInstance(listed.ID, tags[tagHostNode]) {
			continue
		}
		cloud, identity, err := f.reobserveInstance(ctx, listed.ID)
		if err != nil {
			if errors.Is(err, ErrForeignResource) {
				slog.WarnContext(ctx, "withholding OCI instance without a verified regional identity", "instance_id", listed.ID, "region", f.config.Region)
				continue
			}
			return nil, err
		}
		owned, err := f.journal.IsOwnedInstance(ctx, identity)
		if err != nil {
			return nil, fmt.Errorf("read OCI host ownership journal: %w", err)
		}
		if !owned {
			slog.WarnContext(ctx, "withholding OCI instance without durable controller ownership", "instance_id", cloud.ID, "region", f.config.Region, "create_key", identity.CreateKey)
			continue
		}
		profileIntent, found, err := f.journal.GetOperation(ctx, OperationScope{
			Action: actionLaunch, Key: identity.CreateKey, Region: identity.Region,
			Generation: identity.Generation, Owner: identity.Owner,
		})
		if err != nil {
			return nil, fmt.Errorf("read OCI host placement profile: %w", err)
		}
		if !found || profileIntent.Shape != f.config.Shape || !cloudMatchesLaunchBinding(cloud, profileIntent) {
			slog.WarnContext(ctx, "withholding OCI instance that does not match its signed placement compute profile", "instance_id", cloud.ID, "region", f.config.Region, "create_key", identity.CreateKey)
			continue
		}
		instance, err := f.instanceFromCloud(ctx, cloud, identity, profileIntent)
		if err != nil {
			if errors.Is(err, ErrAttachmentRecoveryHold) || errors.Is(err, ErrForeignResource) ||
				errors.Is(err, ErrRetainedVolumeUnknown) {
				slog.WarnContext(ctx, "withholding OCI instance with an unverified retained volume attachment", "instance_id", cloud.ID, "region", f.config.Region, "error", err)
				continue
			}
			return nil, err
		}
		instances = append(instances, instance)
	}
	if tally != nil {
		publishInventory(f.config.Region, tally, f.now())
	}
	return instances, nil
}

func (f *fleet) EnsureHost(ctx context.Context, request EnsureRequest) (Instance, error) {
	if !validCreateKey(request.CreateKey) || !slices.Contains(f.config.FaultDomains, request.FaultDomain) {
		return Instance{}, errors.New("OCI host launch has an invalid create key or unsupported fault domain")
	}
	if !f.memberName(request.Name, false) {
		return Instance{}, fmt.Errorf("OCI host launch name %q is not a member name of this cell", request.Name)
	}
	if !validManagedPrivateIP(request.PrivateIP) {
		return Instance{}, errors.New("OCI host launch requires a signed private IPv4 address")
	}
	if request.Shape != f.config.Shape || !validComputeProfile(request.Shape, request.WholeOCPUs,
		request.MemoryInGBs, request.PlacementProfileDigest, request.PlacementGeneration) {
		return Instance{}, ErrPlacementProfileMismatch
	}
	choice, err := f.launchImage(ctx, request.CreateKey)
	if err != nil {
		return Instance{}, err
	}
	image := choice.image
	descriptor, err := f.hostBootDescriptor(request, image)
	if err != nil {
		return Instance{}, fmt.Errorf("%w: %v", ErrHostBootBindingMismatch, err)
	}
	descriptorWire, err := descriptor.CanonicalBytes()
	if err != nil {
		return Instance{}, fmt.Errorf("%w: encode descriptor: %v", ErrHostBootBindingMismatch, err)
	}
	descriptorDigest, err := descriptor.Digest()
	if err != nil {
		return Instance{}, fmt.Errorf("%w: digest descriptor: %v", ErrHostBootBindingMismatch, err)
	}
	epoch, err := f.currentEpoch()
	if err != nil {
		return Instance{}, err
	}
	release, err := f.beginActiveWorkloadEffect(ctx, epoch, descriptor.DatabaseID, descriptor.PartitionID)
	if err != nil {
		return Instance{}, err
	}
	defer release()
	if err := f.verifyLaunchScope(ctx, descriptor, request.CreateKey); err != nil {
		return Instance{}, err
	}
	intent := f.intent(actionLaunch, request.CreateKey, "", request.CreateKey, "", request.FaultDomain, "")
	intent.Shape = request.Shape
	intent.PrivateIP = request.PrivateIP
	intent.WholeOCPUs = request.WholeOCPUs
	intent.MemoryInGBs = request.MemoryInGBs
	intent.PlacementProfileDigest = request.PlacementProfileDigest
	intent.PlacementGeneration = request.PlacementGeneration
	intent.ImageID = image
	intent.BootDescriptor = string(descriptorWire)
	intent.BootDescriptorSHA256 = descriptorDigest
	if err := f.recordIntent(ctx, epoch, intent); err != nil {
		return Instance{}, err
	}
	priorResult, hasPriorResult, err := f.journal.GetResult(ctx, intent)
	if err != nil {
		return Instance{}, fmt.Errorf("read OCI host operation result: %w", err)
	}
	operationIntent := priorResult.Intent
	if operationIntent.CreatedAt.IsZero() {
		operationIntent = intent
	}
	cloud, identity, found, err := f.findByCreateKey(ctx, request.CreateKey)
	if err != nil {
		if hasPriorResult && !priorResult.Unknown && isNotFound(err) {
			return Instance{}, createRecoveryHold(resourceMemberHost, request.CreateKey, "the previously confirmed instance is missing")
		}
		return Instance{}, err
	}
	if found {
		owned, err := f.journal.IsOwnedInstance(ctx, identity)
		if err != nil {
			return Instance{}, fmt.Errorf("read OCI host ownership journal: %w", err)
		}
		if owned {
			if hasPriorResult && !priorResult.Unknown && priorResult.ResourceID != cloud.ID {
				return Instance{}, createRecoveryHold(resourceMemberHost, request.CreateKey, "the observed instance differs from the immutable confirmed result")
			}
			if cloud.FaultDomain != request.FaultDomain {
				return Instance{}, fmt.Errorf("%w: create key is bound to a different fault domain", ErrForeignResource)
			}
			if !cloudMatchesPlacementProfile(cloud, operationIntent) {
				return Instance{}, fmt.Errorf("%w: observed instance does not match the immutable launch intent", ErrPlacementProfileMismatch)
			}
			if cloud.PrivateIP != operationIntent.PrivateIP {
				return Instance{}, fmt.Errorf("%w: observed private IP differs from immutable launch intent", ErrPlacementProfileMismatch)
			}
			// The launch receipt is immutable; the live ETag belongs to this
			// observation and will fence the next tag/termination operation.
			if err := f.captureBootBinding(ctx, epoch, cloud, identity); err != nil {
				return Instance{}, err
			}
			return f.instanceFromCloud(ctx, cloud, identity, operationIntent)
		}
		if !hasPriorResult || !priorResult.Unknown {
			if hasPriorResult && !priorResult.Unknown {
				return Instance{}, createRecoveryHold(resourceMemberHost, request.CreateKey, "the confirmed instance is no longer positively owned")
			}
			return Instance{}, fmt.Errorf("%w: instance %s has matching tags but no durable provider attempt or ownership", ErrForeignResource, cloud.ID)
		}
	} else if hasPriorResult && !priorResult.Unknown {
		return Instance{}, createRecoveryHold(resourceMemberHost, request.CreateKey, "the previously confirmed instance is missing")
	}
	if err := checkCreateRetryWindow(resourceMemberHost, request.CreateKey, operationIntent, f.now()); err != nil {
		return Instance{}, err
	}
	node := hostNode(f.config, request.CreateKey)
	launch := LaunchRequest{
		DisplayName: request.Name,
		CreateKey:   request.CreateKey,
		Node:        node,
		RetryToken: retryToken(strings.Join([]string{
			f.config.Owner, string(f.config.Region), fmt.Sprint(f.config.Generation), request.CreateKey,
		}, ":")),
		FaultDomain:            operationIntent.FaultDomain,
		PrivateIP:              operationIntent.PrivateIP,
		Shape:                  operationIntent.Shape,
		WholeOCPUs:             operationIntent.WholeOCPUs,
		MemoryInGBs:            operationIntent.MemoryInGBs,
		PlacementProfileDigest: operationIntent.PlacementProfileDigest,
		PlacementGeneration:    operationIntent.PlacementGeneration,
		ImageID:                operationIntent.ImageID,
		BootVolumeGB:           f.config.BootVolumeGB,
		BootVolumeVPUsPerGB:    f.config.BootVolumeVPUsPerGB,
		BootDescriptor:         operationIntent.BootDescriptor,
		FreeformTags: placementProfileTags(
			hostTags(f.config, request.CreateKey), operationIntent.PlacementProfileDigest, operationIntent.PlacementGeneration,
		),
	}
	// The image must still be allowed and qualify right before the provider
	// launch: a replay may run hours after it was journaled, and the cell
	// spec may change between a new launch's choice and this launch.
	if choice.image != operationIntent.ImageID {
		choice = launchChoice{image: operationIntent.ImageID}
	}
	releaseFence, err := f.admitLaunch(ctx, choice)
	if err != nil {
		return Instance{}, err
	}
	fenced := true
	defer func() {
		if fenced {
			releaseFence()
		}
	}()
	if err := f.guard(ctx, epoch); err != nil {
		return Instance{}, err
	}
	if err := checkCreateRetryWindow(resourceMemberHost, request.CreateKey, operationIntent, f.now()); err != nil {
		return Instance{}, err
	}
	created, launchErr := f.provider.LaunchInstance(ctx, launch)
	if launchErr != nil {
		if err := f.guard(ctx, epoch); err != nil {
			return Instance{}, errors.Join(ErrOutcomeUnknown, launchErr, err, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
		}
		if err := checkCreateRetryWindow(resourceMemberHost, request.CreateKey, operationIntent, f.now()); err != nil {
			return Instance{}, errors.Join(err, launchErr, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
		}
		created, launchErr = f.provider.LaunchInstance(ctx, launch)
	}
	fenced = false
	releaseFence()
	if launchErr != nil || created.ID == "" {
		unknownErr := errors.Join(ErrOutcomeUnknown, launchErr, errors.New("OCI launch response did not confirm an instance ID"))
		return Instance{}, errors.Join(unknownErr, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
	}
	cloud, identity, found, err = f.findByCreateKey(ctx, request.CreateKey)
	if err != nil {
		unknownErr := errors.Join(ErrOutcomeUnknown, err)
		return Instance{}, errors.Join(unknownErr, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
	}
	if !found || cloud.ID != created.ID {
		unknownErr := fmt.Errorf("%w: launched instance was not positively re-observed by create key", ErrOutcomeUnknown)
		return Instance{}, errors.Join(unknownErr, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
	}
	if cloud.FaultDomain != request.FaultDomain {
		return Instance{}, fmt.Errorf("%w: create key is bound to a different fault domain", ErrForeignResource)
	}
	if !cloudMatchesPlacementProfile(cloud, operationIntent) {
		unknownErr := fmt.Errorf("%w: %w: launched instance does not match the immutable launch intent", ErrOutcomeUnknown, ErrPlacementProfileMismatch)
		return Instance{}, errors.Join(unknownErr, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
	}
	if cloud.PrivateIP != operationIntent.PrivateIP {
		unknownErr := fmt.Errorf("%w: %w: launched private IP differs from immutable launch intent", ErrOutcomeUnknown, ErrPlacementProfileMismatch)
		return Instance{}, errors.Join(unknownErr, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
	}
	if err := f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, ResourceID: cloud.ID, ETag: cloud.ETag}); err != nil {
		return Instance{}, err
	}
	if err := f.captureBootBinding(ctx, epoch, cloud, identity); err != nil {
		return Instance{}, err
	}
	return f.instanceFromCloud(ctx, cloud, identity, operationIntent)
}

func OpenJournal(ctx context.Context, js jetstream.JetStream, replicas int) (*KVJournal, error) {
	if js == nil || replicas < 1 || replicas > 5 {
		return nil, errors.New("OCI journal requires JetStream and one to five replicas")
	}
	kv, err := js.CreateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket:       journalBucket,
		Description:  "Durable OCI mutation intent and resource ownership",
		MaxValueSize: journalMaxValueSize,
		History:      5,
		Storage:      jetstream.FileStorage,
		Replicas:     replicas,
		Compression:  true,
	})
	if err != nil {
		if !errors.Is(err, jetstream.ErrBucketExists) {
			return nil, fmt.Errorf("create OCI journal bucket: %w", err)
		}
		kv, err = js.KeyValue(ctx, journalBucket)
		if err != nil {
			return nil, fmt.Errorf("open existing OCI journal bucket: %w", err)
		}
		status, statusErr := kv.Status(ctx)
		if statusErr != nil {
			return nil, fmt.Errorf("inspect OCI journal bucket: %w", statusErr)
		}
		config := status.Config()
		if config.Replicas != replicas || config.Storage != jetstream.FileStorage || config.TTL != 0 || config.History < 2 || config.MaxValueSize > journalMaxValueSize {
			return nil, errors.New("existing OCI journal bucket has incompatible durability limits")
		}
	}
	return NewKVJournal(kv)
}

// NewKVJournal wraps a caller-provisioned regional JetStream KV bucket. The
// caller is responsible for using a durable, quorum-replicated bucket.
func NewKVJournal(kv jetstream.KeyValue) (*KVJournal, error) {
	if kv == nil {
		return nil, errors.New("OCI journal KV bucket is required")
	}
	return &KVJournal{kv: kv}, nil
}

func (journal *KVJournal) RecordIntent(ctx context.Context, intent OperationIntent) error {
	if err := validateIntent(intent); err != nil {
		return err
	}
	entry := journalEntry{SchemaVersion: journalSchema, Kind: "operation", Intent: intent}
	data, err := json.Marshal(entry)
	if err != nil {
		return fmt.Errorf("encode OCI operation intent: %w", err)
	}
	key := operationKey(intent)
	_, err = journal.kv.Create(ctx, key, data)
	if err == nil {
		return nil
	}
	if !errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("persist OCI operation intent: %w", err)
	}
	current, err := journal.read(ctx, key)
	if err != nil {
		return err
	}
	if current.Kind != "operation" || !sameIntent(current.Intent, intent) {
		return errors.New("OCI operation key was reused for a different mutation")
	}
	return nil
}

func (journal *KVJournal) GetOperation(ctx context.Context, scope OperationScope) (OperationIntent, bool, error) {
	if scope.Action == "" || scope.Key == "" || scope.Generation == 0 || scope.Owner == "" {
		return OperationIntent{}, false, errors.New("OCI operation lookup scope is incomplete")
	}
	if _, err := scope.Region.OCIRegion(); err != nil {
		return OperationIntent{}, false, err
	}
	keyIntent := OperationIntent{
		Action: scope.Action, Key: scope.Key, Region: scope.Region,
		Generation: scope.Generation, Owner: scope.Owner,
	}
	entry, err := journal.read(ctx, operationKey(keyIntent))
	if errors.Is(err, jetstream.ErrKeyNotFound) || errors.Is(err, jetstream.ErrKeyDeleted) {
		return OperationIntent{}, false, nil
	}
	if err != nil {
		return OperationIntent{}, false, err
	}
	intent := entry.Intent
	if entry.Kind != "operation" || intent.Action != scope.Action || intent.Key != scope.Key ||
		intent.Region != scope.Region || intent.Generation != scope.Generation || intent.Owner != scope.Owner {
		return OperationIntent{}, false, errors.New("OCI operation lookup has no matching durable intent")
	}
	return intent, true, nil
}

