func NewTokenServer(config Config, token string, deps ServerDeps) (*Server, error) {
	checked, err := checkBearerToken([]byte(token))
	if err != nil {
		return nil, err
	}
	// The token stands in for the file Validate requires off loopback.
	config.BearerTokenFile = "token"
	if err := config.Validate(); err != nil {
		return nil, err
	}
	return newServer(config, checked, deps)
}

func newServer(config Config, token []byte, deps ServerDeps) (*Server, error) {
	if deps.Registry == nil || deps.Health == nil {
		return nil, errors.New("observability server requires a registry and health checks")
	}
	manager := &sessions{secure: config.TLSCertFile != ""}
	if deps.LocalSessions {
		manager.local = make(map[string]struct{})
	}
	server := &Server{mux: http.NewServeMux(), deps: deps, sessions: manager, token: token}
	server.catalog = &metricCatalog{registry: deps.Registry}
	if deps.Sessions != nil && token != nil {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if err := server.SetSessionStore(ctx, deps.Sessions); err != nil {
			return nil, err
		}
	}
	server.mux.HandleFunc("GET /healthz", func(writer http.ResponseWriter, _ *http.Request) {
		writePlain(writer, http.StatusOK, "ok\n")
	})
	server.mux.HandleFunc("GET /readyz", server.readyz)
	server.Handle("GET /metrics", http.HandlerFunc(server.metrics))
	server.HandleAuthenticated("GET /v1/metrics/catalog", http.HandlerFunc(server.metricCatalogHTTP))
	if deps.Snapshots != nil {
		server.HandleSnapshots(deps.Snapshots)
	}
	if deps.Cluster != nil {
		server.HandleCluster(deps.Cluster)
	}
	if deps.Events != nil {
		server.Handle("GET /v1/events", http.HandlerFunc(server.events))
	}
	return server, nil
}

func (server *Server) Handle(pattern string, handler http.Handler) {
	server.mux.Handle(pattern, server.authenticate(handler))
}

// HandleAuthenticated never grants tokenless loopback access to this API.
func (server *Server) HandleAuthenticated(pattern string, handler http.Handler) {
	server.Handle(pattern, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if server.token == nil {
			writePlain(w, http.StatusServiceUnavailable, "authenticated API requires a configured token\n")
			return
		}
		handler.ServeHTTP(w, r)
	}))
}

// HandleStatic mounts an unauthenticated route for public embedded files,
// such as the dashboard's stylesheet the login form needs. It must never
// serve cell state.
func (server *Server) HandleStatic(pattern string, handler http.Handler) {
	server.mux.Handle(pattern, handler)
}

// ServeHTTP lets tests and an embedding mux exercise the routes directly.
func (server *Server) ServeHTTP(writer http.ResponseWriter, request *http.Request) {
	// A proxy hop would make the bind address meaningless as an access
	// control, exactly as for the host enrollment listener.
	if request.Header.Get("Forwarded") != "" || request.Header.Get("X-Forwarded-For") != "" ||
		request.Header.Get("X-Real-IP") != "" {
		writePlain(writer, http.StatusBadRequest, "proxied requests are not accepted\n")
		return
	}
	// Without a token the loopback bind is the only control, and DNS
	// rebinding defeats it for any route reachable under a hostname. Every
	// route of a tokenless listener, not only the dashboard's, therefore
	// requires an IP literal or localhost as the Host.
	if server.token == nil && !LiteralHost(request.Host) {
		writePlain(writer, http.StatusMisdirectedRequest, "address this listener by IP or localhost\n")
		return
	}
	server.mux.ServeHTTP(writer, request)
}

// LiteralHost reports whether an HTTP Host header names an IP literal or
// localhost, which a DNS-rebinding page cannot present.
func LiteralHost(host string) bool {
	if name, _, err := net.SplitHostPort(host); err == nil {
		host = name
	} else if len(host) > 1 && host[0] == '[' && host[len(host)-1] == ']' {
		host = host[1 : len(host)-1]
	}
	if host == "localhost" {
		return true
	}
	_, err := netip.ParseAddr(host)
	return err == nil
}

func (server *Server) authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
		if server.token != nil && !bearerMatches(request.Header.Get("Authorization"), server.token) {
			authenticated := false
			if request.Header.Get("Authorization") == "" && server.loginMounted.Load() {
				var err error
				authenticated, err = server.sessions.authenticated(request)
				if err != nil {
					writePlain(writer, http.StatusServiceUnavailable, "session storage unavailable\n")
					return
				}
			}
			if !authenticated {
				if server.loginMounted.Load() && wantsLoginPage(request) {
					http.Redirect(writer, request, "/login?next="+url.QueryEscape(LocalRedirectPath(request.URL.RequestURI())),
						http.StatusSeeOther)
					return
				}
				writer.Header().Set("WWW-Authenticate", `Bearer realm="ts-orch"`)
				writePlain(writer, http.StatusUnauthorized, "unauthorized\n")
				return
			}
		}
		if server.token != nil && server.loginMounted.Load() && request.Header.Get("Authorization") == "" {
			if cookie, err := request.Cookie(SessionCookieName); err == nil {
				http.SetCookie(writer, server.sessions.cookie(cookie.Value))
			}
		}
		next.ServeHTTP(writer, request)
	})
}

func NewView(local string, regions func() []string, now func() time.Time) *View {
	if now == nil {
		now = time.Now
	}
	return &View{
		local:       normalize(local),
		regions:     regions,
		now:         now,
		rollups:     map[string]*Rollup{},
		persisted:   map[string]time.Time{},
		persistedAt: map[string]time.Time{},
		changed:     make(chan struct{}),
	}
}

// Regions lists local first, then every other listed region by cell.
func (v *View) Regions() []Region {
	v.mu.Lock()
	defer v.mu.Unlock()
	cells := v.listed()
	out := make([]Region, 0, len(cells))
	for _, cell := range cells {
		out = append(out, v.region(cell))
	}
	return out
}

// Region returns one listed region; false when cell is not listed.
func (v *View) Region(cell string) (Region, bool) {
	v.mu.Lock()
	defer v.mu.Unlock()
	cell = normalize(cell)
	if !slices.Contains(v.listed(), cell) {
		return Region{}, false
	}
	return v.region(cell), true
}

// Changed returns a channel closed on the next accepted rollup.
func (v *View) Changed() <-chan struct{} {
	v.mu.Lock()
	defer v.mu.Unlock()
	return v.changed
}

// Accept keeps r when it is newer than the held rollup of its cell.
func (v *View) Accept(r Rollup) bool {
	v.mu.Lock()
	defer v.mu.Unlock()
	if validate(r, v.now()) != nil {
		return false
	}
	held := v.rollups[r.Cell]
	if held != nil && !r.ObservedAt.After(held.ObservedAt) {
		return false
	}
	if held == nil && len(v.rollups) >= maxRegions {
		v.prune()
		if len(v.rollups) >= maxRegions {
			return false
		}
	}
	v.rollups[r.Cell] = &r
	close(v.changed)
	v.changed = make(chan struct{})
	return true
}

func Handler(view *View) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /v1/regions", func(writer http.ResponseWriter, request *http.Request) {
		writeJSON(writer, view.Regions())
	})
	mux.HandleFunc("GET /v1/regions/{region}", func(writer http.ResponseWriter, request *http.Request) {
		region, ok := view.Region(request.PathValue("region"))
		if !ok {
			http.Error(writer, "region is not configured", http.StatusNotFound)
			return
		}
		writeJSON(writer, region)
	})
	mountDrilldowns(mux, view)
	mountFunctionViews(mux, view)
	return mux
}

func (region Region) ResourceState(found bool) string {
	switch {
	case region.Rollup == nil:
		return "missing"
	case region.Stale:
		return "stale"
	case !found && region.Rollup.Truncated:
		return "truncated"
	case !found:
		return "not_found"
	default:
		return "current"
	}
}

func mountDrilldowns(mux *http.ServeMux, view *View) {
	for _, resource := range []string{"nodes", "nodes/{node}", "nodes/{node}/services", "nodes/{node}/services/{service}", "volumes", "volumes/{volume}", "services", "services/{service}"} {
		mux.HandleFunc("GET /v1/regions/{region}/"+resource, func(writer http.ResponseWriter, request *http.Request) {
			region, listed := view.Region(request.PathValue("region"))
			result := ResourceView{Version: 1, Cell: region.Cell, State: "not_found"}
			if !listed {
				writeResource(writer, result, http.StatusNotFound)
				return
			}
			if region.Rollup == nil {
				result.State = "missing"
				writeResource(writer, result, http.StatusServiceUnavailable)
				return
			}
			result.ObservedAt, result.Truncated = region.Rollup.ObservedAt, region.Rollup.Truncated
			data, found := drilldownData(region.Rollup, resource, request)
			result.State, result.Data = region.ResourceState(found), data
			if resource == "services" || resource == "services/{service}" {
				observed := region.Rollup.ServicesObservedAt
				for _, service := range region.Rollup.Services {
					if resource == "services" || service.ServiceID == request.PathValue("service") {
						if service.ObservedAt.IsZero() || service.ObservedAt.Before(observed) {
							observed = service.ObservedAt
						}
					}
				}
				result.State = region.ManagedServiceState(found, observed)
				result.ObservedAt = observed
				if result.State == "unavailable" {
					result.Data, found = nil, false
				}
			}
			if (resource == "volumes" || resource == "volumes/{volume}") && region.Rollup.VolumesUnavailable {
				result.State, result.Data = "unavailable", nil
				found = false
			}
			status := http.StatusOK
			if !found {
				status = http.StatusServiceUnavailable
				if result.State == "not_found" {
					status = http.StatusNotFound
				}
			}
			writeResource(writer, result, status)
		})
	}
}

func drilldownData(rollup *Rollup, resource string, request *http.Request) (any, bool) {
	switch resource {
	case "services":
		return slices.Clone(rollup.Services), true
	case "services/{service}":
		if index := slices.IndexFunc(rollup.Services, func(service swarmruntime.ServiceObservation) bool {
			return service.ServiceID == request.PathValue("service")
		}); index >= 0 {
			return rollup.Services[index], true
		}
	case "nodes":
		return append([]Node{}, rollup.Nodes...), true
	case "volumes":
		return append([]Volume{}, rollup.Volumes...), true
	case "volumes/{volume}":
		if index := slices.IndexFunc(rollup.Volumes, func(volume Volume) bool { return volume.ID == request.PathValue("volume") }); index >= 0 {
			return rollup.Volumes[index], true
		}
	default:
		index := slices.IndexFunc(rollup.Nodes, func(node Node) bool { return node.Name == request.PathValue("node") })
		if index < 0 {
			return nil, false
		}
		node := rollup.Nodes[index]
		switch resource {
		case "nodes/{node}":
			return node, true
		case "nodes/{node}/services":
			return append([]Service{}, node.Services...), true
		case "nodes/{node}/services/{service}":
			if index := slices.IndexFunc(node.Services, func(service Service) bool { return service.Role == request.PathValue("service") }); index >= 0 {
				return node.Services[index], true
			}
		}
	}
	return nil, false
}

func writeResource(writer http.ResponseWriter, result ResourceView, status int) {
	writer.Header().Set("Content-Type", "application/json")
	writer.Header().Set("Cache-Control", "no-store")
	writer.Header().Set("X-Content-Type-Options", "nosniff")
	writer.WriteHeader(status)
	writeJSON(writer, result)
}

func mountFunctionViews(mux *http.ServeMux, view *View) {
	for _, path := range []string{"functions", "functions/{tenant}/{function}"} {
		mux.HandleFunc("GET /v1/regions/{region}/"+path, func(w http.ResponseWriter, r *http.Request) {
			region, listed := view.Region(r.PathValue("region"))
			result := ResourceView{Version: 1, Cell: region.Cell, State: "not_found"}
			found := false
			if listed && region.Rollup != nil {
				result.Truncated, result.ObservedAt = region.Rollup.Truncated, region.Rollup.FunctionsObservedAt
				if path == "functions" {
					found, result.Data = true, slices.Clone(region.Rollup.Functions)
					result.State = region.FunctionState(nil, true)
					for _, function := range region.Rollup.Functions {
						if state := region.FunctionState(&function, true); state != "current" {
							result.State = state
							break
						}
					}
				} else {
					var functions []FunctionObservation
					for _, function := range region.Rollup.Functions {
						if function.TenantID == r.PathValue("tenant") && function.FunctionID == r.PathValue("function") {
							functions = append(functions, function)
						}
					}
					found = len(functions) > 0
					result.State = region.FunctionState(nil, found)
					if found {
						result.Data = functions
						for _, function := range functions {
							if state := region.FunctionState(&function, true); state != "current" {
								result.State = state
							}
							if function.ObservedAt.Before(result.ObservedAt) {
								result.ObservedAt = function.ObservedAt
							}
						}
					}
				}
			} else if listed {
				result.State = "missing"
			}
			status := http.StatusOK
			if !found || result.State == "unavailable" && result.Data == nil {
				status = http.StatusServiceUnavailable
				if result.State == "not_found" {
					status = http.StatusNotFound
				}
			}
			writeResource(w, result, status)
		})
	}
}

func (region Region) FunctionState(observation *FunctionObservation, found bool) string {
	if region.Rollup != nil && region.Rollup.FunctionsObservedAt.IsZero() {
		return "unavailable"
	}
	state := region.ResourceState(found)
	if state != "current" && state != "not_found" {
		return state
	}
	observed := region.Rollup.FunctionsObservedAt
	if observation != nil {
		if observation.State != "observed" && observation.State != "unplaced" || observation.State == "observed" && observation.Snapshot == nil {
			return "unavailable"
		}
		observed = observation.ObservedAt
	}
	if observed.IsZero() || region.Rollup.ObservedAt.Sub(observed) > StaleAfter {
		return "stale"
	}
	return state
}

func (region Region) ManagedServiceState(found bool, observed time.Time) string {
	if region.Rollup != nil && region.Rollup.ServicesObservedAt.IsZero() {
		return "unavailable"
	}
	state := region.ResourceState(found)
	if state != "current" && state != "not_found" {
		return state
	}
	if observed.IsZero() || region.Rollup.ObservedAt.Sub(observed) > StaleAfter {
		return "stale"
	}
	return state
}

